import { after } from 'next/server'
import { getAllProducts, syncCatalogFromERP } from '@/lib/db'

// Cache the catalog read so day-to-day browsing is fast and does not re-query
// the data source on every request. The "products" tag is what the sync action
// invalidates, so every view that depends on this catalog stays consistent.
const getProducts = unstable_cache(
  async () => getAllProducts(),
  ['admin-catalog'],
  { tags: ['products'], revalidate: false },
)

// Inline Server Action: triggered by a regular HTML <form> on the page.
// Running the (potentially long) ERP/PIM sync inside `after` lets the action
// return immediately so the admin can keep working. We then mark the
// "products" tag stale with the "max" profile, which serves the current
// (briefly stale) catalog while fresh data is recomputed in the background
// (stale-while-revalidate) across every view that reads the same tag.
async function syncCatalog() {
  'use server'

  after(async () => {
    try {
      await syncCatalogFromERP()
    } catch (error) {
      console.error('[catalog] background sync failed:', error)
    }
    // Invalidate the catalog cache tag. With profile "max", the next request
    // is served stale content while a revalidation runs in the background,
    // so the catalog becomes up to date shortly after across all views.
    revalidateTag('products', 'max')
  })
}

