              fontSize: 14,
              fontWeight: 600,
              background: '#111',
              color: '#fff',
              border: 'none',
              borderRadius: 8,
              cursor: 'pointer',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 24 }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '2px solid #eee' }}>
            <th style={{ padding: '8px 12px' }}>SKU</th>
            <th style={{ padding: '8px 12px' }}>Name</th>
